// visualization.js

// Configuration
const width = 800;
const height = 800; // Keep it square-ish for the bubbles
const margin = {top: 20, right: 20, bottom: 20, left: 20};

// Formatting helpers
const formatCurrency = d3.format("$,.2f");
const formatLargeNumber = (num) => {
    if (!num) return "N/A";
    if (num >= 1e12) return d3.format(".2f")(num / 1e12) + "T";
    if (num >= 1e9) return d3.format(".2f")(num / 1e9) + "B";
    if (num >= 1e6) return d3.format(".2f")(num / 1e6) + "M";
    return d3.format(",")(num);
};

// Main initialization
document.addEventListener('DOMContentLoaded', () => {
    d3.csv('data/stock-descriptions.csv').then(data => {
        // Pre-process data
        data.forEach(d => {
            d.marketCapVal = d.marketCap ? +d.marketCap : 0;
            // Clean up missing values
            d.sector = d.sector || "Unknown";
            d.full_name = d["full name"]; // Handle space in header
        });

        createVisualization(data);
    }).catch(err => {
        console.error("Error loading data:", err);
        d3.select("#chart").append("p").text("Error loading data: " + err.message);
    });
});

function createVisualization(data) {
    // --- 1. Setup Layout & Scales ---

    // Get unique sectors for color scale and clustering
    const sectors = Array.from(new Set(data.map(d => d.sector))).sort();

    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10); // Standard D3 colors

    // Radius scale: Area proportional to Market Cap
    const maxCap = d3.max(data, d => d.marketCapVal);
    const radiusScale = d3.scaleSqrt()
        .domain([0, maxCap])
        .range([5, 60]); // Min radius 5, Max 60

    // --- 2. Create SVG ---
    const svg = d3.select("#chart")
        .append("svg")
        .attr("viewBox", `0 0 ${width} ${height}`)
        .attr("preserveAspectRatio", "xMidYMid meet")
        .classed("chart-svg", true);

    // --- 3. Force Simulation Setup ---

    // Calculate cluster centers for sectors (arranged in a circle)
    const clusterCenters = {};
    const radius = 250; // Radius of the circle of clusters
    sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * 2 * Math.PI - Math.PI / 2; // Start from top
        clusterCenters[sector] = {
            x: width / 2 + Math.cos(angle) * radius,
            y: height / 2 + Math.sin(angle) * radius
        };
    });

    // Initialize nodes
    const nodes = data.map(d => {
        // Determine radius
        let r = 15; // Default for ETFs/Missing
        if (d.sector !== 'ETF' && d.marketCapVal > 0) {
            r = radiusScale(d.marketCapVal);
        }

        return {
            ...d,
            r: r,
            x: width / 2 + (Math.random() - 0.5) * 50, // Initial jitter
            y: height / 2 + (Math.random() - 0.5) * 50
        };
    });

    const simulation = d3.forceSimulation(nodes)
        .force("charge", d3.forceManyBody().strength(-5)) // Slight repulsion
        .force("collide", d3.forceCollide().radius(d => d.r + 2).iterations(2)) // Prevent overlap
        .force("x", d3.forceX(d => clusterCenters[d.sector] ? clusterCenters[d.sector].x : width/2).strength(0.08))
        .force("y", d3.forceY(d => clusterCenters[d.sector] ? clusterCenters[d.sector].y : height/2).strength(0.08))
        .force("center", d3.forceCenter(width / 2, height / 2).strength(0.05));

    // --- 4. Render Bubbles ---

    // Group for bubbles to ensure they are below labels if needed (or use single group)
    const nodeGroup = svg.append("g").attr("class", "nodes");

    const bubbles = nodeGroup.selectAll("g.bubble-group")
        .data(nodes)
        .join("g")
        .attr("class", "bubble-group")
        .attr("id", d => `bubble-${d.ticker}`)
        .on("mouseover", handleMouseOver)
        .on("mouseout", handleMouseOut)
        .on("click", handleClick);

    const circles = bubbles.append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.r)
        .attr("fill", d => colorScale(d.sector));

    const labels = bubbles.append("text")
        .attr("class", "bubble-label")
        .attr("dy", ".3em")
        .text(d => d.ticker)
        .style("font-size", d => Math.min(12, d.r / 1.5) + "px") // Scale text slightly, but cap it
        .style("display", d => d.r > 8 ? "block" : "none"); // Hide label if too small

    // --- 5. Simulation Tick ---
    simulation.on("tick", () => {
        bubbles.attr("transform", d => `translate(${d.x},${d.y})`);
    });

    // --- 6. Render Legends ---
    const legendGroup = svg.append("g")
        .attr("class", "legend")
        .attr("transform", `translate(20, 20)`);

    const legendItems = legendGroup.selectAll(".legend-item")
        .data(sectors)
        .join("g")
        .attr("class", "legend-item")
        .attr("transform", (d, i) => `translate(0, ${i * 20})`);

    legendItems.append("rect")
        .attr("width", 12)
        .attr("height", 12)
        .attr("fill", d => colorScale(d));

    legendItems.append("text")
        .attr("x", 18)
        .attr("y", 10)
        .text(d => d);

    // --- 7. Render Table ---
    const tableBody = d3.select("#stock-table tbody");

    // Sort data for table (optional, maybe by Market Cap desc)
    const tableData = [...data].sort((a, b) => b.marketCapVal - a.marketCapVal);

    const rows = tableBody.selectAll("tr")
        .data(tableData)
        .join("tr")
        .attr("id", d => `row-${d.ticker}`)
        .on("click", handleClick);

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d.full_name);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => d.sector === 'ETF' ? "N/A" : formatLargeNumber(d.marketCapVal));

    // --- 8. Interactions & Tooltip ---
    const tooltip = d3.select("#tooltip");

    function handleMouseOver(event, d) {
        // "ETF entries have no marketCap... do not show tooltip for them"
        if (d.sector === 'ETF') return;

        tooltip.classed("visible", true)
            .html(`
                <strong>${d.ticker}</strong><br/>
                ${d.full_name}<br/>
                <span style="color:${colorScale(d.sector)}">${d.sector}</span>
            `);

        // Position tooltip
        // Use event.pageX/Y for mouse position
        moveTooltip(event);
    }

    function moveTooltip(event) {
        // Adjust for tooltip size to keep on screen
        const tooltipNode = tooltip.node();
        const tooltipRect = tooltipNode.getBoundingClientRect();

        let left = event.pageX + 15;
        let top = event.pageY + 15;

        // Simple boundary check (optional)
        if (left + tooltipRect.width > window.innerWidth) {
            left = event.pageX - tooltipRect.width - 15;
        }

        tooltip
            .style("left", left + "px")
            .style("top", top + "px");
    }

    // Attach move listener to svg to track mouse for tooltip
    bubbles.on("mousemove", moveTooltip);

    function handleMouseOut(event, d) {
        tooltip.classed("visible", false);
    }

    function handleClick(event, d) {
        // d might be from table row or bubble
        const ticker = d.ticker;
        highlight(ticker);
    }

    function highlight(ticker) {
        // 1. Reset all
        d3.selectAll(".bubble").classed("selected", false);
        d3.selectAll("#stock-table tbody tr").classed("selected", false);

        // 2. Select Bubble
        const bubble = d3.select(`#bubble-${ticker} .bubble`);
        if (!bubble.empty()) {
            bubble.classed("selected", true);
        }

        // 3. Select Table Row
        const row = d3.select(`#row-${ticker}`);
        if (!row.empty()) {
            row.classed("selected", true);
            // Scroll to row
            row.node().scrollIntoView({ behavior: "smooth", block: "center" });
        }
    }
}

